cenozoApp.defineModule({name:"reqn_document",models:["add","list","view"],create:module=>{angular.extend(module,{identifier:{parent:{subject:"reqn",column:"reqn.identifier"}},name:{singular:"document",plural:"documents",possessive:"document's"},columnList:{filename:{column:"reqn_document.filename",title:"Name"}},defaultOrder:{column:"reqn_document.filename",reverse:true}});module.addInputGroup("",{data:{title:"File",type:"base64",getFilename:function($state,model){return model.viewModel.record.filename}},filename:{type:"string",isExcluded:true}});cenozo.providers.factory("CnReqnDocumentAddFactory",["CnBaseAddFactory",function(CnBaseAddFactory){var object=function(parentModel){CnBaseAddFactory.construct(this,parentModel);this.onAdd=async function(record){record.filename=this.fileList.findByProperty("key","data").getFilename();await this.$$onAdd(record)}};return{instance:function(parentModel){return new object(parentModel)}}}]);cenozo.providers.factory("CnReqnDocumentViewFactory",["CnBaseViewFactory","CnHttpFactory",function(CnBaseViewFactory,CnHttpFactory){var object=function(parentModel,root){CnBaseViewFactory.construct(this,parentModel,root);const self=this;this.fileList.findByProperty("key","data").postUpload=async function(){await CnHttpFactory.instance({path:self.parentModel.getServiceResourcePath(),data:{filename:this.file.name}}).patch();await self.onView()}};return{instance:function(parentModel,root){return new object(parentModel,root)}}}])}});
